// Spring Boot 3.2 + Java 17: @RestController applies @ResponseBody to every method
@RestController
@RequestMapping("/api/orders")
class OrderController {
    private final OrderService orderService;
    OrderController(OrderService orderService) { this.orderService = orderService; }

    @GetMapping("/{id}")
    Order getOrder(@PathVariable Long id) {
        return orderService.findById(id); // Jackson -> JSON in the response body
    }

    @PostMapping
    Order createOrder(@RequestBody OrderRequest request) { // @RequestBody for INPUT
        return orderService.create(request);
    }
}

record Order(Long id, String item, Double price) {}
record OrderRequest(String item, Double price) {}
