// Spring Boot 3.2: verbs match semantics -> cacheable, retryable, predictable
@RestController
@RequestMapping("/api/products")
class ProductController {
    private final ProductRepository repo;
    ProductController(ProductRepository repo) { this.repo = repo; }

    @GetMapping              List<Product> all()              { return repo.findAll(); }
    @GetMapping("/{id}")     Product one(@PathVariable Long id){ return repo.findById(id).orElseThrow(); }
    @PostMapping            Product create(@RequestBody Product p){ return repo.save(p); }       // 201
    @PutMapping("/{id}")     Product replace(@PathVariable Long id, @RequestBody Product p) {
        p.setId(id); return repo.save(p);                    // idempotent full update
    }
    @DeleteMapping("/{id}")  void remove(@PathVariable Long id){ repo.deleteById(id); }            // 204
}
