// Spring Boot 3.2: 201 with Location, 204 on delete, 200/404 on read
@PostMapping
ResponseEntity<Order> create(@RequestBody Order order) {
    Order saved = service.save(order);
    return ResponseEntity.status(HttpStatus.CREATED)
            .header("Location", "/api/orders/" + saved.id())
            .body(saved);                                  // 201 Created
}

@DeleteMapping("/{id}")
@ResponseStatus(HttpStatus.NO_CONTENT)                       // always 204
void delete(@PathVariable Long id) { service.delete(id); }

@GetMapping("/{id}")
ResponseEntity<Order> get(@PathVariable Long id) {
    return service.find(id)
            .map(ResponseEntity::ok)                        // 200 if present
            .orElse(ResponseEntity.notFound().build());     // 404 if absent
}
