// Spring Boot 3.2 + Java 17: handle each exception once, return a structured body
@RestControllerAdvice
class GlobalExceptionHandler {

    @ExceptionHandler(ResourceNotFoundException.class)
    ResponseEntity<ErrorResponse> notFound(ResourceNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .body(new ErrorResponse(404, ex.getMessage(), LocalDateTime.now()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    ResponseEntity<ErrorResponse> invalid(MethodArgumentNotValidException ex) {
        String msg = ex.getBindingResult().getFieldErrors().stream()
            .map(f -> f.getField() + ": " + f.getDefaultMessage())
            .collect(Collectors.joining(", "));
        return ResponseEntity.badRequest().body(new ErrorResponse(400, msg, LocalDateTime.now()));
    }

    @ExceptionHandler(Exception.class)            // catch-all: never leak stack traces
    ResponseEntity<ErrorResponse> generic(Exception ex) {
        return ResponseEntity.status(500)
            .body(new ErrorResponse(500, "Unexpected error", LocalDateTime.now()));
    }
}

record ErrorResponse(int status, String message, LocalDateTime timestamp) {}
```

Now controllers just throw; the advice maps each exception to a consistent HTTP response.
